from __future__ import annotations

from pathlib import Path

from linkedin_to_github.core import (
    parse_linkedin_connections,
    read_worklist_usernames,
    write_links_html,
    write_users_txt,
    write_worklist_csv,
)


def test_parse_and_outputs(tmp_path: Path) -> None:
    connections = tmp_path / "Connections.csv"
    connections.write_text(
        "\n".join(
            [
                "Notes: this file was generated by LinkedIn",
                "Notes: more notes",
                "First Name,Last Name,URL,Email Address,Company,Position,Connected On",
                "Ada,Lovelace,https://www.linkedin.com/in/ada,ada@example.com,Analytical Engines,Mathematician,2024-01-01",
                "Grace,Hopper,https://www.linkedin.com/in/grace,grace@example.com,US Navy,Rear Admiral,2024-02-01",
            ]
        ),
        encoding="utf-8",
    )

    items = parse_linkedin_connections(connections)
    assert len(items) == 2
    assert items[0].name == "Ada Lovelace"

    out_csv = tmp_path / "github_lookup_worklist.csv"
    out_html = tmp_path / "github_lookup_links.html"
    write_worklist_csv(items, out_csv)
    write_links_html(items, out_html)

    assert out_csv.exists()
    assert out_html.exists()
    csv_text = out_csv.read_text(encoding="utf-8")
    assert "github_username" in csv_text
    assert "Ada Lovelace" in csv_text

    html_text = out_html.read_text(encoding="utf-8")
    assert "<table" in html_text
    assert "Ada Lovelace" in html_text


def test_users_txt_from_worklist(tmp_path: Path) -> None:
    worklist = tmp_path / "github_lookup_worklist.csv"
    worklist.write_text(
        "\n".join(
            [
                "name,linkedin_url,company,position,email,connected_on,github_username,notes,google,google_company,google_site_github,google_site_role,github_search",
                "Ada Lovelace,https://linkedin/ada,AE,Math,ada@x,2024-01-01,octocat,,x,x,x,x,x",
                "Grace Hopper,https://linkedin/grace,USN,Admiral,grace@x,2024-02-01,@hubot,,x,x,x,x,x",
                "Dup,https://linkedin/dup,,,dup@x,2024-03-01,octocat,,x,x,x,x,x",
            ]
        ),
        encoding="utf-8",
    )

    usernames = read_worklist_usernames(worklist)
    assert usernames == ["octocat", "hubot"]

    out_users = tmp_path / "users.txt"
    write_users_txt(usernames, out_users)
    assert out_users.read_text(encoding="utf-8").splitlines() == ["octocat", "hubot"]
